module.header:
extern const pdm_instance_t ${module.driver.pdm.name};
extern pdm_instance_ctrl_t ${module.driver.pdm.name}_ctrl;
extern const pdm_cfg_t ${module.driver.pdm.name}_cfg;
#ifndef ${module.driver.pdm.callback}
void ${module.driver.pdm.callback}(pdm_callback_args_t * p_args);
#endif

module.declarations:
pdm_instance_ctrl_t ${module.driver.pdm.name}_ctrl;
const pdm_extended_cfg_t ${module.driver.pdm.name}_cfg_extend =
{
    .microphone_startup_us = ${module.driver.pdm.microphone_startup_us},
};
const pdm_cfg_t ${module.driver.pdm.name}_cfg =
{
    .channel = ${module.driver.pdm.channel},
    .mode = ${module.driver.pdm.mode},
    .ipl = ${module.driver.pdm.ipl},
    .dat_irq = { VECTOR_NUMBER_PDM_DAT${module.driver.pdm.channel},
#if ${module.driver.pdm.falling_ipl} != BSP_IRQ_DISABLED
        VECTOR_NUMBER_PDM_DAT1
#else
        FSP_INVALID_VECTOR
#endif
    },
    .err_irq = { VECTOR_NUMBER_PDM_ERR${module.driver.pdm.channel},
#if ${module.driver.pdm.falling_ipl} != BSP_IRQ_DISABLED
        VECTOR_NUMBER_PDM_ERR1
#else
        FSP_INVALID_VECTOR
#endif
    },
    .p_callback = ${module.driver.pdm.callback},
    .p_context = NULL,
    .p_extend = &${module.driver.pdm.name}_cfg_extend,
};
const pdm_instance_t ${module.driver.pdm.name} =
{
    .p_ctrl = &${module.driver.pdm.name}_ctrl,
    .p_cfg = &${module.driver.pdm.name}_cfg,
    .p_api = &g_pdm_on_pdm,
};
